//! Native Go SDK generation for Kaji.
//!
//! This crate consumes only the neutral [`Api`] model.  It deliberately does
//! not know about OpenAPI files, the Go sidecar, or a JavaScript runtime.

use std::{collections::BTreeMap, fmt::Write};

use anyhow::{Result, bail};
use kaji_core::{
    AdditionalProperties, Api, GeneratedFile, GeneratedTree, Operation, OperationParameter, Schema,
    SchemaKind, SchemaValue, SdkClientStyle,
};
use serde_json::Value;

const NOTICE: &str = "// Code generated by Kaji. DO NOT EDIT.\n";

/// Generates a self-contained Go SDK package beneath `output_dir`.
///
/// `package_name` is both the Go package identifier and, after normalization,
/// the module name used in `go.mod`. Passing `None` derives it from the API
/// name. The output is intentionally returned as a [`GeneratedTree`] so the
/// caller controls where and when it is materialized.
pub fn generate_go_sdk(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
) -> Result<GeneratedTree> {
    generate_go_sdk_with_style(api, output_dir, package_name, SdkClientStyle::Flat)
}

/// Generates a Go SDK with either direct operations or resource namespaces.
///
/// [`SdkClientStyle::Flat`] preserves the original `client.GetContact(...)`
/// surface. [`SdkClientStyle::Namespaced`] additionally initializes resource
/// fields such as `client.Contacts.Get(...)`; direct operations remain public
/// for a gradual migration.
pub fn generate_go_sdk_with_style(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
    client_style: SdkClientStyle,
) -> Result<GeneratedTree> {
    let output_dir = normalized_output_dir(output_dir)?;
    let package = package_name
        .map(go_package_name)
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| go_package_name(&api.name));
    if package.is_empty() {
        bail!("a Go package name could not be derived from the API name")
    }

    let module = go_module_name(package_name.unwrap_or(&api.name));
    let mut tree = GeneratedTree::default();
    tree.insert(GeneratedFile::new(
        output_path(&output_dir, "go.mod"),
        render_go_mod(&module),
    )?)?;
    tree.insert(GeneratedFile::new(
        output_path(&output_dir, "models.go"),
        render_models(api, &package),
    )?)?;
    tree.insert(GeneratedFile::new(
        output_path(&output_dir, "client.go"),
        render_client(api, &package, client_style),
    )?)?;
    tree.insert(GeneratedFile::new(
        output_path(&output_dir, "README.md"),
        render_readme(api, client_style),
    )?)?;
    if client_style == SdkClientStyle::Namespaced {
        tree.insert(GeneratedFile::new(
            output_path(&output_dir, "STYLE_GUIDE.md"),
            render_style_guide(api),
        )?)?;
    }
    Ok(tree)
}

fn normalized_output_dir(output_dir: &str) -> Result<String> {
    let output_dir = output_dir.trim_matches('/');
    if output_dir.is_empty() || output_dir == "." {
        return Ok(String::new());
    }
    if output_dir.split('/').any(|component| component == "..") {
        bail!("Go SDK output directory cannot contain parent-directory components")
    }
    Ok(output_dir.to_owned())
}

fn output_path(output_dir: &str, file: &str) -> String {
    if output_dir.is_empty() {
        file.to_owned()
    } else {
        format!("{output_dir}/{file}")
    }
}

fn render_go_mod(module: &str) -> String {
    format!("module {module}\n\ngo 1.22\n")
}

fn render_models(api: &Api, package: &str) -> String {
    let mut output = format!("{NOTICE}\npackage {package}\n\n");
    if api
        .schemas
        .iter()
        .any(|schema| schema_needs_json(&schema.value))
    {
        output.push_str("import \"encoding/json\"\n\n");
    }
    for schema in &api.schemas {
        render_schema(&mut output, schema);
        output.push('\n');
    }
    output
}

fn schema_needs_json(value: &SchemaValue) -> bool {
    match &value.kind {
        SchemaKind::OneOf { .. } | SchemaKind::AnyOf { .. } | SchemaKind::AllOf { .. } => true,
        SchemaKind::Array { items } => schema_needs_json(items),
        SchemaKind::Object {
            fields,
            additional_properties,
        } => {
            fields.iter().any(|field| schema_needs_json(&field.value))
                || matches!(
                    additional_properties,
                    AdditionalProperties::Schema { value } if schema_needs_json(value)
                )
        }
        SchemaKind::Not { schema } => schema_needs_json(schema),
        _ => false,
    }
}

fn render_schema(output: &mut String, schema: &Schema) {
    let name = go_type_name(&schema.name);
    match &schema.value.kind {
        SchemaKind::Object {
            fields,
            additional_properties,
        } => {
            let _ = writeln!(output, "type {name} struct {{");
            for field in fields {
                let field_name = go_type_name(&field.name);
                let mut field_type = go_type(&field.value);
                if !field.required && !field_type.starts_with('*') {
                    field_type = format!("*{field_type}");
                }
                let omitempty = if field.required { "" } else { ",omitempty" };
                let _ = writeln!(
                    output,
                    "\t{field_name} {field_type} `json:\"{}{omitempty}\"`",
                    field.name
                );
            }
            if let AdditionalProperties::Schema { value } = additional_properties {
                let _ = writeln!(
                    output,
                    "\tAdditionalProperties map[string]{} `json:\"-\"`",
                    go_type(value)
                );
            }
            output.push_str("}\n");
        }
        SchemaKind::String if !schema.value.enum_values.is_empty() => {
            let _ = writeln!(output, "type {name} string\n");
            output.push_str("const (\n");
            for (index, value) in schema.value.enum_values.iter().enumerate() {
                let value = value.as_str().unwrap_or_default();
                let constant = format!("{name}{}", go_type_name(value));
                let _ = writeln!(output, "\t{constant} {name} = {value:?}");
                if value.is_empty() {
                    let _ = writeln!(output, "\t_ = {index}");
                }
            }
            output.push_str(")\n");
        }
        _ => {
            let _ = writeln!(output, "type {name} = {}", go_type(&schema.value));
        }
    }
}

fn render_client(api: &Api, package: &str, client_style: SdkClientStyle) -> String {
    let resources = resource_operations(api);
    let facade_fields = if client_style == SdkClientStyle::Namespaced {
        resources
            .keys()
            .map(|resource| {
                let facade = resource_facade_name(resource, &resources);
                format!("\t{facade} *{facade}Service\n")
            })
            .collect::<String>()
    } else {
        String::new()
    };
    let facade_setup = if client_style == SdkClientStyle::Namespaced {
        resources
            .keys()
            .map(|resource| {
                let facade = resource_facade_name(resource, &resources);
                format!("\tclient.{facade} = &{facade}Service{{client: client}}\n")
            })
            .collect::<String>()
    } else {
        String::new()
    };
    let mut output = format!(
        "{NOTICE}\npackage {package}\n\nimport (\n\t\"bytes\"\n\t\"context\"\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"io\"\n\t\"net/http\"\n\t\"net/url\"\n\t\"reflect\"\n\t\"strings\"\n)\n\n// ClientConfig configures a generated API client.\ntype ClientConfig struct {{\n\tBaseURL      string\n\tAPIKey       string\n\tAPIKeyHeader string\n\tAPIKeyPrefix string\n\tHTTPClient   *http.Client\n}}\n\n// Client is safe for concurrent use after construction.\ntype Client struct {{\n\tbaseURL      string\n\tapiKey       string\n\tapiKeyHeader string\n\tapiKeyPrefix string\n\thttpClient   *http.Client\n{facade_fields}}}\n\n// NewClient builds a client from explicit configuration. BaseURL is required.\nfunc NewClient(config ClientConfig) (*Client, error) {{\n\tbaseURL := strings.TrimRight(config.BaseURL, \"/\")\n\tif baseURL == \"\" {{\n\t\treturn nil, fmt.Errorf(\"kaji: BaseURL is required\")\n\t}}\n\theader := config.APIKeyHeader\n\tif header == \"\" {{\n\t\theader = \"Authorization\"\n\t}}\n\thttpClient := config.HTTPClient\n\tif httpClient == nil {{\n\t\thttpClient = http.DefaultClient\n\t}}\n\tclient := &Client{{baseURL: baseURL, apiKey: config.APIKey, apiKeyHeader: header, apiKeyPrefix: config.APIKeyPrefix, httpClient: httpClient}}\n{facade_setup}\treturn client, nil\n}}\n\n// APIError describes a non-success HTTP response.\ntype APIError struct {{\n\tStatusCode int\n\tBody       string\n}}\n\nfunc (errorResponse *APIError) Error() string {{\n\treturn fmt.Sprintf(\"kaji: API request failed with status %d: %s\", errorResponse.StatusCode, errorResponse.Body)\n}}\n\nfunc (client *Client) newRequest(ctx context.Context, method, path string, query url.Values, headers http.Header, body any) (*http.Request, error) {{\n\tendpoint := client.baseURL + path\n\tif len(query) > 0 {{\n\t\tendpoint += \"?\" + query.Encode()\n\t}}\n\tvar reader io.Reader\n\tif body != nil {{\n\t\tencoded, err := json.Marshal(body)\n\t\tif err != nil {{\n\t\t\treturn nil, fmt.Errorf(\"kaji: encode request body: %w\", err)\n\t\t}}\n\t\treader = bytes.NewReader(encoded)\n\t}}\n\trequest, err := http.NewRequestWithContext(ctx, method, endpoint, reader)\n\tif err != nil {{\n\t\treturn nil, fmt.Errorf(\"kaji: build request: %w\", err)\n\t}}\n\trequest.Header.Set(\"Accept\", \"application/json\")\n\tif body != nil {{\n\t\trequest.Header.Set(\"Content-Type\", \"application/json\")\n\t}}\n\tfor name, values := range headers {{\n\t\tfor _, value := range values {{\n\t\t\trequest.Header.Add(name, value)\n\t\t}}\n\t}}\n\tif client.apiKey != \"\" {{\n\t\tcredential := client.apiKey\n\t\tif client.apiKeyPrefix != \"\" {{\n\t\t\tcredential = client.apiKeyPrefix + \" \" + credential\n\t\t}}\n\t\trequest.Header.Set(client.apiKeyHeader, credential)\n\t}}\n\treturn request, nil\n}}\n\nfunc (client *Client) do(request *http.Request, destination any) error {{\n\tresponse, err := client.httpClient.Do(request)\n\tif err != nil {{\n\t\treturn fmt.Errorf(\"kaji: execute request: %w\", err)\n\t}}\n\tdefer response.Body.Close()\n\tif response.StatusCode < http.StatusOK || response.StatusCode >= http.StatusMultipleChoices {{\n\t\tbody, _ := io.ReadAll(io.LimitReader(response.Body, 1<<20))\n\t\treturn &APIError{{StatusCode: response.StatusCode, Body: string(body)}}\n\t}}\n\tif destination == nil || response.StatusCode == http.StatusNoContent {{\n\t\treturn nil\n\t}}\n\tif err := json.NewDecoder(response.Body).Decode(destination); err != nil && err != io.EOF {{\n\t\treturn fmt.Errorf(\"kaji: decode response: %w\", err)\n\t}}\n\treturn nil\n}}\n\nfunc addQuery(query url.Values, name string, value any) error {{\n\tif value == nil {{\n\t\treturn nil\n\t}}\n\treflected := reflect.ValueOf(value)\n\tif reflected.Kind() == reflect.Pointer {{\n\t\tif reflected.IsNil() {{\n\t\t\treturn nil\n\t\t}}\n\t\treturn addQuery(query, name, reflected.Elem().Interface())\n\t}}\n\tif reflected.Kind() == reflect.Slice || reflected.Kind() == reflect.Array {{\n\t\tfor index := 0; index < reflected.Len(); index++ {{\n\t\t\tif err := addQuery(query, name, reflected.Index(index).Interface()); err != nil {{\n\t\t\t\treturn err\n\t\t\t}}\n\t\t}}\n\t\treturn nil\n\t}}\n\tswitch value.(type) {{\n\tcase string, bool, int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:\n\t\tquery.Add(name, fmt.Sprint(value))\n\t\treturn nil\n\tdefault:\n\t\tencoded, err := json.Marshal(value)\n\t\tif err != nil {{\n\t\t\treturn fmt.Errorf(\"kaji: encode query %s: %w\", name, err)\n\t\t}}\n\t\tquery.Add(name, string(encoded))\n\t\treturn nil\n\t}}\n\n"
    );
    output = output.replace(
        "func (client *Client) newRequest(ctx context.Context, method, path string, query url.Values, headers http.Header, body any) (*http.Request, error) {\n\tendpoint := client.baseURL + path\n\tif len(query) > 0 {\n\t\tendpoint += \"?\" + query.Encode()\n\t}\n\tvar reader io.Reader",
        "func (client *Client) newRequest(ctx context.Context, method, path string, query url.Values, headers http.Header, body any) (*http.Request, error) {\n\tendpoint := client.baseURL + path\n\tif len(query) > 0 { endpoint += \"?\" + query.Encode() }\n\treturn client.newRequestURL(ctx, method, endpoint, headers, body)\n}\n\n// newPaginationRequest is private on purpose: a generated pager may follow\n// only a same-origin URL supplied by its declared response contract. It still\n// uses the normal request builder, so auth, caller headers, and body encoding\n// cannot be bypassed by a continuation link.\nfunc (client *Client) newPaginationRequest(ctx context.Context, method, continuation string, headers http.Header, body any) (*http.Request, error) {\n\tbase, err := url.Parse(client.baseURL)\n\tif err != nil { return nil, fmt.Errorf(\"kaji: parse BaseURL: %w\", err) }\n\tnext, err := url.Parse(continuation)\n\tif err != nil { return nil, fmt.Errorf(\"kaji: parse pagination URL: %w\", err) }\n\tendpoint := base.ResolveReference(next)\n\tif endpoint.Scheme != base.Scheme || endpoint.Host != base.Host {\n\t\treturn nil, fmt.Errorf(\"kaji: pagination URL must remain on the configured API origin\")\n\t}\n\treturn client.newRequestURL(ctx, method, endpoint.String(), headers, body)\n}\n\nfunc (client *Client) newRequestURL(ctx context.Context, method, endpoint string, headers http.Header, body any) (*http.Request, error) {\n\tvar reader io.Reader",
    );
    // A spec can legitimately define a model called APIError. Keep the
    // transport error private so it can never collide with exported models.
    output = output.replace("APIError", "kajiAPIError");
    // The format literal closes `addQuery`'s switch; this closes the helper.
    output.push_str("}\n\n");

    for operation in &api.operations {
        render_operation(&mut output, operation);
        render_cursor_pager(&mut output, api, operation);
        if cursor_pagination(api, operation).is_none() {
            render_offset_pager(&mut output, operation);
        }
        render_url_pager(&mut output, operation);
    }
    if api.operations.iter().any(|operation| {
        cursor_pagination(api, operation).is_some()
            || offset_pagination(operation).is_some()
            || url_pagination(operation).is_some()
    }) {
        output.push_str(PAGINATION_RUNTIME);
    }
    if client_style == SdkClientStyle::Namespaced {
        output.push_str(&render_namespaced_facade(&resources));
    }
    add_retry_runtime(output)
}

fn add_retry_runtime(mut output: String) -> String {
    let needs_errors = output.contains("errors.As(");
    output = output.replace(
        "\t\"strings\"\n)",
        if needs_errors {
            "\t\"errors\"\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n)"
        } else {
            "\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n)"
        },
    );
    output = output.replace(
        "\tBody       string\n",
        "\tBody        []byte\n\tContentType string\n",
    );
    output = output.replace(
        "errorResponse.StatusCode, errorResponse.Body)",
        "errorResponse.StatusCode, string(errorResponse.Body))",
    );
    output = output.replace(
        "Body: string(body)",
        "Body: body, ContentType: response.Header.Get(\"Content-Type\")",
    );
    output = output.replace(
        "\tHTTPClient   *http.Client\n}",
        "\tHTTPClient   *http.Client\n\t// Retry configures safe automatic retries. Nil uses Kaji defaults; set\n\t// MaxAttempts to 1 to disable retries.\n\tRetry        *RetryConfig\n}",
    );
    output = output.replace(
        "\thttpClient   *http.Client\n",
        "\thttpClient   *http.Client\n\tretry        retryConfig\n",
    );
    output = output.replace(
        "client := &Client{baseURL: baseURL, apiKey: config.APIKey, apiKeyHeader: header, apiKeyPrefix: config.APIKeyPrefix, httpClient: httpClient}",
        "client := &Client{baseURL: baseURL, apiKey: config.APIKey, apiKeyHeader: header, apiKeyPrefix: config.APIKeyPrefix, httpClient: httpClient, retry: normalizeRetry(config.Retry)}",
    );
    output = output.replace("client.do(request,", "client.doWithRetry(request,");
    output.push_str(include_str!("go_retry_runtime.txt"));
    output
}

#[derive(Clone, Debug)]
enum GoResponseKind {
    None,
    Json(String),
    Text,
    Binary,
    EventStream,
}

const PAGINATION_RUNTIME: &str = r#"
// kajiPaginationString reads a simple declared JSONPath from a page response.
// It intentionally supports object paths (for example $.meta.nextCursor); a
// malformed or non-string value simply ends iteration rather than guessing.
func kajiPaginationString(value any, path string) (string, bool) {
	encoded, err := json.Marshal(value)
	if err != nil { return "", false }
	var current any
	if err := json.Unmarshal(encoded, &current); err != nil { return "", false }
	path = strings.TrimPrefix(path, "$")
	for _, segment := range strings.Split(strings.TrimPrefix(path, "."), ".") {
		if segment == "" { continue }
		object, ok := current.(map[string]any)
		if !ok { return "", false }
		current, ok = object[segment]
		if !ok { return "", false }
	}
	cursor, ok := current.(string)
	return cursor, ok && cursor != ""
}

// kajiPaginationArrayLen reads a declared results array. It returns false for
// malformed paths or non-array values so generated pagers stop safely.
func kajiPaginationArrayLen(value any, path string) (int, bool) {
	encoded, err := json.Marshal(value)
	if err != nil { return 0, false }
	var current any
	if err := json.Unmarshal(encoded, &current); err != nil { return 0, false }
	path = strings.TrimPrefix(path, "$")
	for _, segment := range strings.Split(strings.TrimPrefix(path, "."), ".") {
		if segment == "" { continue }
		object, ok := current.(map[string]any)
		if !ok { return 0, false }
		current, ok = object[segment]
		if !ok { return 0, false }
	}
	items, ok := current.([]any)
	return len(items), ok
}

"#;

#[derive(Clone, Debug)]
enum GoCursorLocation {
    Parameter {
        name: String,
        optional: bool,
    },
    /// Request-body cursor pagers are deliberately limited to a named object
    /// schema with an optional string field. That lets us clone and update a
    /// typed request without mutating the caller's value or guessing JSON.
    RequestBody {
        body_type: String,
        field_name: String,
        body_required: bool,
    },
}

#[derive(Clone, Debug)]
struct GoCursorPagination {
    location: GoCursorLocation,
    next_cursor_path: String,
}

#[derive(Clone, Debug)]
struct GoUrlPagination {
    next_url_path: String,
}

#[derive(Clone, Debug)]
struct GoOffsetPagination {
    offset_name: String,
    limit_name: String,
    results_path: String,
}

fn offset_parameter(operation: &Operation, inputs: &[Value], kind: &str) -> Option<String> {
    let input = inputs
        .iter()
        .find(|input| input.get("type").and_then(Value::as_str) == Some(kind))?
        .as_object()?;
    if !matches!(
        input.get("in").and_then(Value::as_str),
        None | Some("parameters")
    ) {
        return None;
    }
    let name = input.get("name")?.as_str()?;
    operation
        .parameters
        .iter()
        .find(|parameter| {
            parameter.name == name
                && !parameter.required
                && matches!(
                    parameter.schema.as_ref().map(|schema| &schema.kind),
                    Some(SchemaKind::Integer)
                )
        })
        .map(|parameter| parameter.name.clone())
}

fn offset_pagination(operation: &Operation) -> Option<GoOffsetPagination> {
    let extension = operation
        .annotations
        .get("x-kaji-pagination")
        .or_else(|| operation.annotations.get("x-speakeasy-pagination"))?
        .as_object()?;
    if extension.get("type").and_then(Value::as_str) != Some("offsetLimit") {
        return None;
    }
    let inputs = extension.get("inputs")?.as_array()?;
    Some(GoOffsetPagination {
        offset_name: offset_parameter(operation, inputs, "offset")?,
        limit_name: offset_parameter(operation, inputs, "limit")?,
        results_path: extension
            .get("outputs")?
            .get("results")?
            .as_str()?
            .to_owned(),
    })
}

fn cursor_pagination(api: &Api, operation: &Operation) -> Option<GoCursorPagination> {
    let extension = operation
        .annotations
        .get("x-kaji-pagination")
        .or_else(|| operation.annotations.get("x-speakeasy-pagination"))?
        .as_object()?;
    if extension.get("type")?.as_str()? != "cursor" {
        return None;
    }
    let input = extension
        .get("inputs")?
        .as_array()?
        .iter()
        .find(|input| input.get("type").and_then(|value| value.as_str()) == Some("cursor"))?
        .as_object()?;
    let cursor_name = input.get("name")?.as_str()?;
    let next_cursor_path = extension
        .get("outputs")?
        .get("nextCursor")?
        .as_str()?
        .to_owned();
    let location = if input.get("in").and_then(Value::as_str) == Some("requestBody") {
        body_cursor_location(api, operation, cursor_name)?
    } else {
        let parameter = operation.parameters.iter().find(|parameter| {
            parameter.name == cursor_name
                && matches!(parameter.location.as_str(), "query" | "header" | "path")
                && matches!(
                    parameter.schema.as_ref().map(|schema| &schema.kind),
                    Some(SchemaKind::String)
                )
        })?;
        // OpenAPI path parameters are always required. Do not turn an invalid
        // optional path parameter into a paginator API.
        if parameter.location == "path" && !parameter.required {
            return None;
        }
        GoCursorLocation::Parameter {
            name: parameter.name.clone(),
            optional: !parameter.required,
        }
    };
    Some(GoCursorPagination {
        location,
        next_cursor_path,
    })
}

fn body_cursor_location(
    api: &Api,
    operation: &Operation,
    cursor_name: &str,
) -> Option<GoCursorLocation> {
    let body = operation.request_body.as_ref()?;
    let schema = body
        .media_types
        .iter()
        .find(|media| media.content_type.contains("json"))
        .or_else(|| body.media_types.first())?
        .schema
        .as_ref()?;
    let SchemaKind::Reference { reference } = &schema.kind else {
        return None;
    };
    let body_name = reference.rsplit('/').next()?;
    let body_schema = api.schemas.iter().find(|schema| schema.name == body_name)?;
    let SchemaKind::Object { fields, .. } = &body_schema.value.kind else {
        return None;
    };
    let field = fields.iter().find(|field| {
        field.name == cursor_name
            && !field.required
            && matches!(field.value.kind, SchemaKind::String)
    })?;
    Some(GoCursorLocation::RequestBody {
        body_type: go_type_name(body_name),
        field_name: go_type_name(&field.name),
        body_required: body.required,
    })
}

fn url_pagination(operation: &Operation) -> Option<GoUrlPagination> {
    let extension = operation
        .annotations
        .get("x-kaji-pagination")
        .or_else(|| operation.annotations.get("x-speakeasy-pagination"))?
        .as_object()?;
    if extension.get("type").and_then(Value::as_str) != Some("url") {
        return None;
    }
    Some(GoUrlPagination {
        next_url_path: extension
            .get("outputs")?
            .get("nextUrl")?
            .as_str()?
            .to_owned(),
    })
}

fn operation_response_kind(operation: &Operation) -> GoResponseKind {
    let media = operation
        .responses
        .iter()
        .find(|response| response.status.starts_with('2'))
        .or_else(|| {
            operation
                .responses
                .iter()
                .find(|response| response.status == "default")
        })
        .and_then(|response| response.media_types.first());
    let Some(media) = media else {
        return operation_response_type(operation)
            .map(GoResponseKind::Json)
            .unwrap_or(GoResponseKind::None);
    };
    let content_type = media.content_type.to_ascii_lowercase();
    if content_type.starts_with("text/event-stream") {
        return GoResponseKind::EventStream;
    }
    if content_type.contains("json") {
        return GoResponseKind::Json(
            media
                .schema
                .as_ref()
                .map(go_type)
                .or_else(|| operation_response_type(operation))
                .unwrap_or_else(|| "any".into()),
        );
    }
    if content_type.starts_with("text/") {
        return GoResponseKind::Text;
    }
    if content_type.starts_with("application/octet-stream")
        || media.schema.as_ref().is_some_and(|schema| {
            matches!(&schema.kind, SchemaKind::String)
                && matches!(schema.format.as_deref(), Some("binary") | Some("byte"))
        })
    {
        return GoResponseKind::Binary;
    }
    media
        .schema
        .as_ref()
        .map(go_type)
        .map(GoResponseKind::Json)
        .unwrap_or(GoResponseKind::None)
}

fn error_responses(operation: &Operation) -> impl Iterator<Item = &kaji_core::OperationResponse> {
    operation.responses.iter().filter(|response| {
        response.status == "default"
            || response
                .status
                .parse::<u16>()
                .is_ok_and(|status| (400..600).contains(&status))
    })
}

fn declared_error_name(operation: &Operation, status: &str) -> String {
    let suffix = if status == "default" {
        "Default".to_owned()
    } else {
        status.to_owned()
    };
    format!("{}Error{suffix}", go_type_name(&operation.id))
}

fn render_declared_errors(output: &mut String, operation: &Operation) {
    for response in error_responses(operation) {
        let name = declared_error_name(operation, &response.status);
        let media = response.media_types.first();
        let body_type = media.and_then(|media| media.schema.as_ref()).map(go_type);
        let _ = writeln!(
            output,
            "// {name} is returned when {} responds with status {}.",
            go_type_name(&operation.id),
            response.status
        );
        let _ = writeln!(output, "type {name} struct {{");
        output.push_str("\tStatusCode int\n\tRawBody    []byte\n");
        if let Some(body_type) = &body_type {
            let _ = writeln!(output, "\tBody       {body_type}");
        }
        output.push_str("}\n\n");
        let _ = writeln!(output, "func (errorResponse *{name}) Error() string {{");
        let _ = writeln!(
            output,
            "\treturn fmt.Sprintf(\"kaji: {} failed with status %d\", errorResponse.StatusCode)",
            go_type_name(&operation.id)
        );
        output.push_str("}\n\n");
    }
    if error_responses(operation).next().is_none() {
        return;
    }
    let decoder = format!("decode{}Error", go_type_name(&operation.id));
    let _ = writeln!(output, "func {decoder}(requestError error) error {{");
    output.push_str("\tvar transportError *kajiAPIError\n\tif !errors.As(requestError, &transportError) { return requestError }\n\tswitch transportError.StatusCode {\n");
    for response in error_responses(operation) {
        if response.status == "default" {
            continue;
        }
        let name = declared_error_name(operation, &response.status);
        let _ = writeln!(output, "\tcase {}:", response.status);
        let _ = writeln!(
            output,
            "\t\tresult := &{name}{{StatusCode: transportError.StatusCode, RawBody: transportError.Body}}"
        );
        render_error_body_decode(output, response, "result");
        output.push_str("\t\treturn result\n");
    }
    if let Some(default_response) =
        error_responses(operation).find(|response| response.status == "default")
    {
        let name = declared_error_name(operation, "default");
        output.push_str("\tdefault:\n");
        let _ = writeln!(
            output,
            "\t\tresult := &{name}{{StatusCode: transportError.StatusCode, RawBody: transportError.Body}}"
        );
        render_error_body_decode(output, default_response, "result");
        output.push_str("\t\treturn result\n");
    } else {
        output.push_str("\tdefault:\n\t\treturn requestError\n");
    }
    output.push_str("\t}\n}\n\n");
}

fn render_error_body_decode(
    output: &mut String,
    response: &kaji_core::OperationResponse,
    target: &str,
) {
    let Some(schema) = response
        .media_types
        .first()
        .and_then(|media| media.schema.as_ref())
    else {
        return;
    };
    let content_type = response
        .media_types
        .first()
        .map(|media| media.content_type.as_str())
        .unwrap_or_default();
    if content_type.contains("json") {
        let _ = writeln!(
            output,
            "\t\tif len(transportError.Body) > 0 {{ _ = json.Unmarshal(transportError.Body, &{target}.Body) }}"
        );
    } else if content_type.starts_with("text/") && matches!(&schema.kind, SchemaKind::String) {
        let _ = writeln!(output, "\t\t{target}.Body = string(transportError.Body)");
    } else if matches!(&schema.kind, SchemaKind::String)
        && matches!(schema.format.as_deref(), Some("binary") | Some("byte"))
    {
        let _ = writeln!(
            output,
            "\t\t{target}.Body = append([]byte(nil), transportError.Body...)"
        );
    }
}

fn operation_error_expression(operation: &Operation, error: &str) -> String {
    if error_responses(operation).next().is_some() {
        format!("decode{}Error({error})", go_type_name(&operation.id))
    } else {
        error.to_owned()
    }
}

fn render_operation(output: &mut String, operation: &Operation) {
    let operation_name = go_type_name(&operation.id);
    let request_name = format!("{operation_name}Request");
    let has_input = !operation.parameters.is_empty() || operation.request_body.is_some();
    if has_input {
        let _ = writeln!(
            output,
            "// {request_name} contains the inputs for {operation_name}."
        );
        let _ = writeln!(output, "type {request_name} struct {{");
        for parameter in &operation.parameters {
            render_parameter_field(output, parameter);
        }
        if let Some(body) = &operation.request_body {
            let body_type = body
                .media_types
                .iter()
                .find(|media_type| media_type.content_type.contains("json"))
                .or_else(|| body.media_types.first())
                .and_then(|media_type| media_type.schema.as_ref())
                .map(go_type)
                .or_else(|| operation.request_type.as_deref().map(go_operation_type))
                .unwrap_or_else(|| "any".into());
            let body_type = if body.required || body_type.starts_with('*') {
                body_type
            } else {
                format!("*{body_type}")
            };
            let _ = writeln!(output, "\tBody {body_type} `json:\"body,omitempty\"`");
        }
        output.push_str("}\n\n");
    }

    render_declared_errors(output, operation);
    let response_kind = operation_response_kind(operation);
    let parameters = if has_input {
        format!(", input *{request_name}")
    } else {
        String::new()
    };
    let result = match &response_kind {
        GoResponseKind::None => "error".to_owned(),
        GoResponseKind::Json(response) => format!("(*{response}, error)"),
        GoResponseKind::Text => "(string, error)".to_owned(),
        GoResponseKind::Binary => "([]byte, error)".to_owned(),
        GoResponseKind::EventStream => "(io.ReadCloser, error)".to_owned(),
    };
    let _ = writeln!(
        output,
        "// {operation_name} invokes {} {}.\nfunc (client *Client) {operation_name}(ctx context.Context{parameters}) {result} {{",
        operation.method.as_str(),
        operation.path
    );
    if has_input {
        output.push_str("\tif input == nil {\n\t\tinput = &");
        output.push_str(&request_name);
        output.push_str("{}\n\t}\n");
    }
    let _ = writeln!(output, "\tpath := {:?}", operation.path);
    output.push_str("\tquery := url.Values{}\n\theaders := http.Header{}\n");
    for parameter in &operation.parameters {
        render_parameter_use(output, parameter, &response_kind);
    }
    if has_input && operation.request_body.is_some() {
        output.push_str("\tbody := input.Body\n");
    } else {
        output.push_str("\tvar body any\n");
    }
    let _ = writeln!(
        output,
        "\trequest, err := client.newRequest(ctx, {:?}, path, query, headers, body)",
        operation.method.as_str()
    );
    output.push_str("\tif err != nil {\n");
    render_error_return(
        output,
        &response_kind,
        &operation_error_expression(operation, "err"),
    );
    output.push_str("\t}\n");
    match response_kind {
        GoResponseKind::None => {
            output.push_str("\tif err := client.do(request, nil); err != nil {\n");
            render_error_return(
                output,
                &GoResponseKind::None,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn nil\n}\n\n");
        }
        GoResponseKind::Json(response) => {
            let _ = writeln!(output, "\tvar response {response}");
            output.push_str("\tif err := client.do(request, &response); err != nil {\n");
            render_error_return(
                output,
                &GoResponseKind::Json(response.clone()),
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn &response, nil\n}\n\n");
        }
        GoResponseKind::Text => {
            output.push_str(
                "\tvar response string\n\tif err := client.do(request, &response); err != nil {\n",
            );
            render_error_return(
                output,
                &GoResponseKind::Text,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn response, nil\n}\n\n");
        }
        GoResponseKind::Binary => {
            output.push_str(
                "\tvar response []byte\n\tif err := client.do(request, &response); err != nil {\n",
            );
            render_error_return(
                output,
                &GoResponseKind::Binary,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn response, nil\n}\n\n");
        }
        GoResponseKind::EventStream => {
            output.push_str("\tresponse, err := client.stream(request)\n\tif err != nil {\n");
            render_error_return(
                output,
                &GoResponseKind::EventStream,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn response, nil\n}\n\n");
        }
    }
}

fn render_cursor_pager(output: &mut String, api: &Api, operation: &Operation) {
    let Some(pagination) = cursor_pagination(api, operation) else {
        return;
    };
    let GoResponseKind::Json(response_type) = operation_response_kind(operation) else {
        return;
    };
    let operation_name = go_type_name(&operation.id);
    let request_name = format!("{operation_name}Request");
    let pager_name = format!("{operation_name}Pager");
    let cursor_update = match &pagination.location {
        GoCursorLocation::Parameter { name, optional } => {
            let field = go_type_name(name);
            if *optional {
                format!("\tif pager.started {{ pager.input.{field} = &pager.cursor }}\n")
            } else {
                format!("\tif pager.started {{ pager.input.{field} = pager.cursor }}\n")
            }
        }
        GoCursorLocation::RequestBody {
            body_type,
            field_name,
            body_required,
        } => {
            if *body_required {
                format!(
                    "\tif pager.started {{\n\t\tbodyCopy := pager.input.Body\n\t\tbodyCopy.{field_name} = &pager.cursor\n\t\tpager.input.Body = bodyCopy\n\t}}\n"
                )
            } else {
                format!(
                    "\tif pager.started {{\n\t\tif pager.input.Body == nil {{ return nil, fmt.Errorf(\"kaji: cursor pagination requires a {body_type} body\") }}\n\t\tbodyCopy := *pager.input.Body\n\t\tbodyCopy.{field_name} = &pager.cursor\n\t\tpager.input.Body = &bodyCopy\n\t}}\n"
                )
            }
        }
    };
    let body_preflight = match &pagination.location {
        GoCursorLocation::RequestBody {
            body_type,
            body_required: false,
            ..
        } => format!(
            "\tif pager.input.Body == nil {{ return nil, fmt.Errorf(\"kaji: cursor pagination requires a {body_type} body\") }}\n"
        ),
        _ => String::new(),
    };
    let _ = writeln!(
        output,
        "// {pager_name} iterates pages returned by {operation_name}."
    );
    let _ = writeln!(output, "type {pager_name} struct {{");
    let _ = writeln!(
        output,
        "\tclient *Client\n\tinput *{request_name}\n\tcursor string\n\tstarted bool\n\tdone bool\n}}"
    );
    let _ = writeln!(
        output,
        "// {operation_name}Pages starts cursor pagination without guessing fields from a response."
    );
    let _ = writeln!(
        output,
        "func (client *Client) {operation_name}Pages(input *{request_name}) *{pager_name} {{"
    );
    let _ = writeln!(output, "\tcopyInput := &{request_name}{{}}");
    output.push_str("\tif input != nil { *copyInput = *input }\n");
    let _ = writeln!(
        output,
        "\treturn &{pager_name}{{client: client, input: copyInput}}\n}}"
    );
    let _ = writeln!(
        output,
        "// Next returns the next full response page, or io.EOF after the final page."
    );
    let _ = writeln!(
        output,
        "func (pager *{pager_name}) Next(ctx context.Context) (*{response_type}, error) {{"
    );
    output.push_str("\tif pager.done { return nil, io.EOF }\n");
    output.push_str(&body_preflight);
    output.push_str(&cursor_update);
    let _ = writeln!(
        output,
        "\tresponse, err := pager.client.{operation_name}(ctx, pager.input)"
    );
    output.push_str("\tif err != nil { return nil, err }\n");
    let _ = writeln!(
        output,
        "\tcursor, ok := kajiPaginationString(response, {:?})",
        pagination.next_cursor_path
    );
    output.push_str("\tif !ok { pager.done = true; return response, nil }\n\tpager.cursor = cursor\n\tpager.started = true\n\treturn response, nil\n}\n\n");
}

fn render_offset_pager(output: &mut String, operation: &Operation) {
    let Some(pagination) = offset_pagination(operation) else {
        return;
    };
    let GoResponseKind::Json(response_type) = operation_response_kind(operation) else {
        return;
    };
    let operation_name = go_type_name(&operation.id);
    let request_name = format!("{operation_name}Request");
    let pager_name = format!("{operation_name}Pager");
    let offset_field = go_type_name(&pagination.offset_name);
    let limit_field = go_type_name(&pagination.limit_name);
    let _ = writeln!(
        output,
        "// {pager_name} iterates declared offset/limit pages returned by {operation_name}."
    );
    let _ = writeln!(output, "type {pager_name} struct {{");
    let _ = writeln!(
        output,
        "\tclient *Client\n\tinput *{request_name}\n\toffset int64\n\tlimit *int64\n\tdone bool\n}}"
    );
    let _ = writeln!(
        output,
        "// {operation_name}Pages starts declared offset/limit pagination."
    );
    let _ = writeln!(
        output,
        "func (client *Client) {operation_name}Pages(input *{request_name}) *{pager_name} {{"
    );
    let _ = writeln!(output, "\tcopyInput := &{request_name}{{}}");
    output.push_str("\tif input != nil { *copyInput = *input }\n");
    let _ = writeln!(output, "\toffset := int64(0)");
    let _ = writeln!(
        output,
        "\tif copyInput.{offset_field} != nil {{ offset = *copyInput.{offset_field} }}"
    );
    let _ = writeln!(
        output,
        "\treturn &{pager_name}{{client: client, input: copyInput, offset: offset, limit: copyInput.{limit_field}}}\n}}"
    );
    let _ = writeln!(
        output,
        "// Next returns the next full response page, or io.EOF after the final page."
    );
    let _ = writeln!(
        output,
        "func (pager *{pager_name}) Next(ctx context.Context) (*{response_type}, error) {{"
    );
    output.push_str("\tif pager.done { return nil, io.EOF }\n");
    let _ = writeln!(output, "\tpager.input.{offset_field} = &pager.offset");
    let _ = writeln!(
        output,
        "\tresponse, err := pager.client.{operation_name}(ctx, pager.input)"
    );
    output.push_str("\tif err != nil { return nil, err }\n");
    let _ = writeln!(
        output,
        "\tcount, ok := kajiPaginationArrayLen(response, {:?})",
        pagination.results_path
    );
    output.push_str("\tif !ok || count == 0 { pager.done = true; return response, nil }\n");
    output.push_str("\tpager.offset += int64(count)\n");
    output
        .push_str("\tif pager.limit != nil && int64(count) < *pager.limit { pager.done = true }\n");
    output.push_str("\treturn response, nil\n}\n\n");
}

fn render_url_pager(output: &mut String, operation: &Operation) {
    let Some(pagination) = url_pagination(operation) else {
        return;
    };
    let GoResponseKind::Json(response_type) = operation_response_kind(operation) else {
        return;
    };
    let operation_name = go_type_name(&operation.id);
    let request_name = format!("{operation_name}Request");
    let pager_name = format!("{operation_name}Pager");
    let has_input = !operation.parameters.is_empty() || operation.request_body.is_some();
    let input_field = if has_input {
        format!("\tinput *{request_name}\n")
    } else {
        String::new()
    };
    let constructor_input = if has_input {
        format!("input *{request_name}")
    } else {
        String::new()
    };
    let constructor_copy = if has_input {
        format!(
            "\tcopyInput := &{request_name}{{}}\n\tif input != nil {{ *copyInput = *input }}\n\treturn &{pager_name}{{client: client, input: copyInput}}\n"
        )
    } else {
        format!("\treturn &{pager_name}{{client: client}}\n")
    };
    let initial_call = if has_input {
        format!("pager.client.{operation_name}(ctx, pager.input)")
    } else {
        format!("pager.client.{operation_name}(ctx)")
    };
    let mut continuation_prep = String::from("\theaders := http.Header{}\n");
    if has_input {
        render_pagination_headers(&mut continuation_prep, operation);
    }
    if has_input && operation.request_body.is_some() {
        continuation_prep.push_str("\tbody := pager.input.Body\n");
    } else {
        continuation_prep.push_str("\tvar body any\n");
    }
    let error_expression = operation_error_expression(operation, "err");
    let _ = writeln!(
        output,
        "// {pager_name} follows declared same-origin continuation URLs for {operation_name}."
    );
    let _ = writeln!(output, "type {pager_name} struct {{");
    let _ = writeln!(
        output,
        "\tclient *Client\n{input_field}\tnextURL string\n\tstarted bool\n\tdone bool\n}}"
    );
    let _ = writeln!(
        output,
        "// {operation_name}Pages starts URL pagination using the operation's normal typed request.\nfunc (client *Client) {operation_name}Pages({constructor_input}) *{pager_name} {{"
    );
    output.push_str(&constructor_copy);
    output.push_str("}\n");
    let _ = writeln!(
        output,
        "// Next returns the next full response page, or io.EOF after the final page.\nfunc (pager *{pager_name}) Next(ctx context.Context) (*{response_type}, error) {{"
    );
    output.push_str("\tif pager.done { return nil, io.EOF }\n");
    output.push_str("\tif !pager.started {\n");
    let _ = writeln!(output, "\t\tresponse, err := {initial_call}");
    output.push_str("\t\tif err != nil { return nil, err }\n");
    let _ = writeln!(
        output,
        "\t\tnextURL, ok := kajiPaginationString(response, {:?})",
        pagination.next_url_path
    );
    output.push_str("\t\tpager.started = true\n\t\tif !ok { pager.done = true; return response, nil }\n\t\tpager.nextURL = nextURL\n\t\treturn response, nil\n\t}\n");
    output.push_str(&continuation_prep);
    let _ = writeln!(
        output,
        "\trequest, err := pager.client.newPaginationRequest(ctx, {:?}, pager.nextURL, headers, body)",
        operation.method.as_str()
    );
    let _ = writeln!(
        output,
        "\tif err != nil {{ return nil, {error_expression} }}"
    );
    let _ = writeln!(output, "\tvar response {response_type}");
    let _ = writeln!(
        output,
        "\tif err := pager.client.doWithRetry(request, &response); err != nil {{ return nil, {error_expression} }}"
    );
    let _ = writeln!(
        output,
        "\tnextURL, ok := kajiPaginationString(&response, {:?})",
        pagination.next_url_path
    );
    output.push_str("\tif !ok { pager.done = true } else { pager.nextURL = nextURL }\n\treturn &response, nil\n}\n\n");
}

fn render_pagination_headers(output: &mut String, operation: &Operation) {
    for parameter in &operation.parameters {
        if parameter.location != "header" {
            continue;
        }
        let field = format!("pager.input.{}", go_type_name(&parameter.name));
        if parameter.required {
            let _ = writeln!(
                output,
                "\theaders.Set({:?}, fmt.Sprint({field}))",
                parameter.name
            );
        } else {
            let _ = writeln!(
                output,
                "\tif {field} != nil {{ headers.Set({:?}, fmt.Sprint(*{field})) }}",
                parameter.name
            );
        }
    }
}

fn render_parameter_field(output: &mut String, parameter: &OperationParameter) {
    let name = go_type_name(&parameter.name);
    let mut value_type = parameter
        .schema
        .as_ref()
        .map(go_type)
        .unwrap_or_else(|| "any".into());
    if !parameter.required && !value_type.starts_with('*') {
        value_type = format!("*{value_type}");
    }
    let _ = writeln!(
        output,
        "\t{name} {value_type} `json:\"{},omitempty\"`",
        parameter.name
    );
}

fn render_parameter_use(
    output: &mut String,
    parameter: &OperationParameter,
    response_kind: &GoResponseKind,
) {
    let field = format!("input.{}", go_type_name(&parameter.name));
    match parameter.location.as_str() {
        "path" => {
            let _ = writeln!(
                output,
                "\tpath = strings.ReplaceAll(path, {:?}, url.PathEscape(fmt.Sprint({field})))",
                format!("{{{}}}", parameter.name)
            );
        }
        "query" => {
            let _ = writeln!(
                output,
                "\tif err := addQuery(query, {:?}, {field}); err != nil {{",
                parameter.name
            );
            render_error_return(output, response_kind, "err");
            output.push_str("\t}\n");
        }
        "header" => {
            if parameter.required {
                let _ = writeln!(
                    output,
                    "\theaders.Set({:?}, fmt.Sprint({field}))",
                    parameter.name
                );
            } else {
                let _ = writeln!(
                    output,
                    "\tif {field} != nil {{ headers.Set({:?}, fmt.Sprint(*{field})) }}",
                    parameter.name
                );
            }
        }
        _ => {}
    }
}

fn render_error_return(output: &mut String, response_kind: &GoResponseKind, error: &str) {
    match response_kind {
        GoResponseKind::None => {
            let _ = writeln!(output, "\t\treturn {error}");
        }
        GoResponseKind::Text => {
            let _ = writeln!(output, "\t\treturn \"\", {error}");
        }
        GoResponseKind::Json(_) | GoResponseKind::Binary | GoResponseKind::EventStream => {
            let _ = writeln!(output, "\t\treturn nil, {error}");
        }
    }
}

fn operation_response_type(operation: &Operation) -> Option<String> {
    let schema = operation
        .responses
        .iter()
        .find(|response| response.status.starts_with('2'))
        .or_else(|| {
            operation
                .responses
                .iter()
                .find(|response| response.status == "default")
        })
        .and_then(|response| {
            response
                .media_types
                .iter()
                .find(|media_type| media_type.content_type.contains("json"))
                .or_else(|| response.media_types.first())
        })
        .and_then(|media_type| media_type.schema.as_ref())
        .map(go_type);
    schema.or_else(|| match operation.response_type.as_str() {
        "" | "void" | "nil" => None,
        name => Some(go_operation_type(name)),
    })
}

fn go_operation_type(value: &str) -> String {
    match value.to_ascii_lowercase().as_str() {
        "any" | "unknown" | "object" | "null" => "any".into(),
        "boolean" | "bool" => "bool".into(),
        "integer" | "int" | "int64" => "int64".into(),
        "number" | "float" | "float64" => "float64".into(),
        "string" => "string".into(),
        "array" => "[]any".into(),
        _ => go_type_name(value),
    }
}

fn go_type(value: &SchemaValue) -> String {
    let value_type = match &value.kind {
        SchemaKind::Any | SchemaKind::Null | SchemaKind::Not { .. } => "any".into(),
        SchemaKind::Boolean => "bool".into(),
        SchemaKind::Integer => "int64".into(),
        SchemaKind::Number => "float64".into(),
        SchemaKind::String => match value.format.as_deref() {
            Some("binary") | Some("byte") => "[]byte".into(),
            _ => "string".into(),
        },
        SchemaKind::Array { items } => format!("[]{}", go_type(items)),
        SchemaKind::Object {
            additional_properties,
            ..
        } => match additional_properties {
            AdditionalProperties::Schema { value } => format!("map[string]{}", go_type(value)),
            _ => "map[string]any".into(),
        },
        SchemaKind::Reference { reference } => {
            go_type_name(reference.rsplit('/').next().unwrap_or(reference))
        }
        SchemaKind::OneOf { .. } | SchemaKind::AnyOf { .. } | SchemaKind::AllOf { .. } => {
            "json.RawMessage".into()
        }
    };
    if value.nullable && value_type != "any" && !value_type.starts_with('*') {
        format!("*{value_type}")
    } else {
        value_type
    }
}

fn resource_operations(api: &Api) -> BTreeMap<String, Vec<&Operation>> {
    let mut resources = BTreeMap::<String, Vec<&Operation>>::new();
    for operation in &api.operations {
        resources
            .entry(go_type_name(&resource_name(operation)))
            .or_default()
            .push(operation);
    }
    resources
}

fn resource_name(operation: &Operation) -> String {
    operation
        .annotations
        .get("tags")
        .and_then(|tags| tags.as_array())
        .and_then(|tags| tags.first())
        .and_then(|tag| tag.as_str())
        .filter(|tag| !tag.trim().is_empty())
        .map(str::to_owned)
        .or_else(|| {
            operation
                .path
                .split('/')
                .filter(|segment| !segment.is_empty() && !segment.starts_with('{'))
                .find(|segment| {
                    !matches!(*segment, "api" | "email") && !is_version_segment(segment)
                })
                .map(str::to_owned)
        })
        .unwrap_or_else(|| "api".into())
}

fn is_version_segment(segment: &str) -> bool {
    let mut characters = segment.chars();
    matches!(characters.next(), Some('v' | 'V'))
        && characters
            .next()
            .is_some_and(|character| character.is_ascii_digit())
}

fn render_namespaced_facade(resources: &BTreeMap<String, Vec<&Operation>>) -> String {
    let mut output = String::new();
    for (resource, operations) in resources {
        let facade = resource_facade_name(resource, resources);
        let _ = writeln!(output, "// {facade}Service groups {resource} operations.");
        let _ = writeln!(output, "type {facade}Service struct {{ client *Client }}\n");
        let mut used_methods = BTreeMap::<String, usize>::new();
        for operation in operations {
            let direct = go_type_name(&operation.id);
            let preferred = resource_method_name(&direct, resource);
            let seen = used_methods.entry(preferred.clone()).or_default();
            let method = if *seen == 0 {
                preferred
            } else {
                direct.clone()
            };
            *seen += 1;
            render_namespaced_operation(
                &mut output,
                resource,
                &facade,
                &method,
                &direct,
                operation,
            );
        }
    }
    output
}

/// Go selectors share a namespace with methods. A resource whose generated
/// field matches any direct operation therefore receives a stable `Resource`
/// suffix instead of producing an uncompilable client (for example an
/// `auth-check` resource alongside `Client.AuthCheck`).
fn resource_facade_name(resource: &str, resources: &BTreeMap<String, Vec<&Operation>>) -> String {
    if resources
        .values()
        .flatten()
        .any(|operation| go_type_name(&operation.id) == resource)
    {
        format!("{resource}Resource")
    } else {
        resource.to_owned()
    }
}

fn resource_method_name(operation: &str, resource: &str) -> String {
    let singular = resource.strip_suffix('s').unwrap_or(resource);
    operation
        .strip_suffix(resource)
        .or_else(|| operation.strip_suffix(singular))
        .or_else(|| operation.strip_prefix(resource))
        .filter(|method| !method.is_empty())
        .unwrap_or(operation)
        .into()
}

fn render_namespaced_operation(
    output: &mut String,
    resource: &str,
    facade: &str,
    method: &str,
    direct: &str,
    operation: &Operation,
) {
    let request = format!("{direct}Request");
    let has_input = !operation.parameters.is_empty() || operation.request_body.is_some();
    let parameters = if has_input {
        format!(", input *{request}")
    } else {
        String::new()
    };
    let response = operation_response_type(operation);
    let result = response
        .as_deref()
        .map(|response| format!("(*{response}, error)"))
        .unwrap_or_else(|| "error".into());
    let _ = writeln!(
        output,
        "// {method} invokes {direct} through the {resource} namespace.\nfunc (service *{facade}Service) {method}(ctx context.Context{parameters}) {result} {{"
    );
    if has_input {
        let _ = writeln!(output, "\treturn service.client.{direct}(ctx, input)\n}}\n");
    } else {
        let _ = writeln!(output, "\treturn service.client.{direct}(ctx)\n}}\n");
    }
}

fn render_readme(api: &Api, style: SdkClientStyle) -> String {
    let usage = match style {
        SdkClientStyle::Flat => "client.GetContact(ctx, input)",
        SdkClientStyle::Namespaced => "client.Contacts.Get(ctx, input)",
    };
    format!(
        "# {} Go SDK\n\nGenerated by Kaji. This package exposes the `{}` client style. Direct operations remain available in either mode. Generate with `SdkClientStyle::Flat` for `client.GetContact(...)`, or `SdkClientStyle::Namespaced` for resource-first calls such as `client.Contacts.Get(...)`.\n\n```go\nclient, err := NewClient(ClientConfig{{BaseURL: \"https://api.example.com\"}})\nif err != nil {{ panic(err) }}\n_ = {}\n```\n",
        api.name, usage, usage
    )
}

fn render_style_guide(api: &Api) -> String {
    format!(
        "# {} Go SDK styles\n\nKaji supports two stable client surfaces:\n\n- `SdkClientStyle::Flat`: `client.GetContact(ctx, input)`\n- `SdkClientStyle::Namespaced`: `client.Contacts.Get(ctx, input)`\n\nThe namespaced surface is initialized by `NewClient` and delegates to the same typed operation methods, so both styles can coexist during migration.\n\n```go\nclient, err := NewClient(ClientConfig{{BaseURL: \"https://api.example.com\"}})\nif err != nil {{ panic(err) }}\ncontact, err := client.Contacts.Get(ctx, &GetContactRequest{{}})\n_ = contact\n_ = err\n```\n",
        api.name
    )
}

fn go_package_name(value: &str) -> String {
    let mut package = identifier_words(value)
        .into_iter()
        .map(|word| word.to_ascii_lowercase())
        .collect::<String>();
    if package.is_empty() {
        return package;
    }
    if package.as_bytes().first().is_some_and(u8::is_ascii_digit) {
        package.insert(0, 'v');
    }
    match package.as_str() {
        "type" | "var" | "func" | "package" | "map" | "chan" | "interface" | "struct" | "go"
        | "defer" | "select" | "range" => format!("{package}sdk"),
        _ => package,
    }
}

fn go_module_name(value: &str) -> String {
    let slug = identifier_words(value)
        .into_iter()
        .map(|word| word.to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join("-");
    if slug.is_empty() {
        "kaji/sdk".into()
    } else {
        slug
    }
}

fn go_type_name(value: &str) -> String {
    let mut name = identifier_words(value)
        .into_iter()
        .map(|word| go_exported_word(&word))
        .collect::<String>();
    if name.is_empty() {
        name = "Value".into();
    }
    if name.as_bytes().first().is_some_and(u8::is_ascii_digit) {
        name.insert(0, 'V');
    }
    name
}

fn go_exported_word(word: &str) -> String {
    match word.to_ascii_lowercase().as_str() {
        "api" => "API".into(),
        "id" => "ID".into(),
        "http" => "HTTP".into(),
        "https" => "HTTPS".into(),
        "json" => "JSON".into(),
        "oauth" => "OAuth".into(),
        "url" => "URL".into(),
        "uri" => "URI".into(),
        "uuid" => "UUID".into(),
        _ => {
            let mut chars = word.chars();
            match chars.next() {
                Some(first) => first.to_ascii_uppercase().to_string() + chars.as_str(),
                None => String::new(),
            }
        }
    }
}

fn identifier_words(value: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut current = String::new();
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            if character.is_ascii_uppercase()
                && !current.is_empty()
                && current
                    .chars()
                    .last()
                    .is_some_and(|last| last.is_ascii_lowercase())
            {
                words.push(std::mem::take(&mut current));
            }
            current.push(character);
        } else if !current.is_empty() {
            words.push(std::mem::take(&mut current));
        }
    }
    if !current.is_empty() {
        words.push(current);
    }
    words
}

